import hmac
import hashlib
import trafaret as t

def check_body(val):
    if isinstance(val, str) or isinstance(val, bytes):
        return val
    raise t.DataError('Invalid webhook body. Expected: string or bytes')

def check_headers(headers):
    if not isinstance(headers, dict):
        raise t.DataError('value is not a dict')

    headers = {k.lower(): v for k, v in headers.items()}
    for item in ('fs-signature', 'fs-timestamp'):
        if item not in headers:  # Check the lowercase version of the header names
            raise t.DataError('{} header is missing'.format(item))
    return headers

VerificationArguments = t.Dict({
    'secret': t.String,
    'body': t.Call(check_body),
    'headers': t.Call(check_headers)
})

def verify_webhook_signature(secret=None, body=None, headers=None):
    """
    Checks if webhook, which you received was sent by Filestack,
    based on your secret for webhook endpoint which was generated in the Filestack developer portal.
    Body is supposed to be the raw content of the received webhook.

    Returns:
    Tuple: 
        - Positive verification result: (True, {})
        - Negative verification result: (False, {'error': 'error details'})
    """
    try:
        VerificationArguments.check({
            'secret': secret, 'body': body, 'headers': headers
        })
    except t.DataError as e:
        return False, {'error': str(e.as_dict())}

    # Ensure headers are consistently lowercase
    lowercase_headers = {k.lower(): v for k, v in headers.items()}

    # Decode the body if it's in bytes
    if isinstance(body, bytes):
        body = body.decode('utf-8')

    # Construct the HMAC data string
    hmac_data = '{}.{}'.format(body, lowercase_headers['fs-timestamp'])

    # Calculate the HMAC signature
    signature = hmac.new(secret.encode('utf-8'), hmac_data.encode('utf-8'), hashlib.sha256).hexdigest()

    # Get the expected signature from the headers
    expected = lowercase_headers['fs-signature']

    # Compare the signature with the expected value
    if signature != expected:
        return False, {'error': 'Signature mismatch! Expected: {}. Got: {}'.format(expected, signature)}

    return True, {}

